# Analysis & Pre-Thinking

## Core Requirements
1. **Mobile auto-collapse**: When ChatInputBox loses focus on mobile, automatically collapse to pill state
2. **Merge Messenger & QuickChat**: Consolidate shared functionality between MessengerView and QuickChatView into a single component to reduce code duplication and improve maintainability

## Strategic Approach
1. **ChatInputBox focus handling**: Add blur event listener to collapse on mobile
2. **Component analysis**: Compare both views to identify shared logic
3. **Create unified component**: Merge into a single flexible component that handles both modes
4. **Update imports**: Update file references in project

## Dependencies & Risks
- Both views share: chat loading, message rendering, IntelliSense, input handling, file attachment
- Differences: sidebar layout, header variations, group info panel (Messenger only), workspace apps (QuickChat only)
- Risk: Ensure both modes work correctly after merge; test mobile/desktop transitions

## Target Files
- `src/components/chat/ChatInputBox.vue` - Add blur-to-collapse on mobile
- Create `src/views/UnifiedChatView.vue` - Merged component
- Update imports in router/relevant files

---

# Implementation

## Step 1: Update ChatInputBox.vue - Auto-collapse on blur

```vue src/components/chat/ChatInputBox.vue
<script setup>
import ChatInputToolbar from './ChatInputToolbar.vue'
import EmojiPicker from './EmojiPicker.vue'
</script>

<template>
  <div
    class="notion-composer flex flex-col transition-all duration-200 text-sm md:text-base"
    :class="[
      isDraggingOver
        ? 'bg-primary/10 ring-2 ring-primary rounded-lg md:rounded-xl'
        : isFocused
          ? 'bg-base-100 ring-1 ring-base-300 shadow-md rounded-lg md:rounded-xl'
          : 'bg-base-200/60 rounded-lg md:rounded-xl hover:bg-base-200 hover:ring-1 hover:ring-base-300'
    ]"
    @dragover.prevent="isDraggingOver = true"
    @dragleave.prevent="isDraggingOver = false"
    @drop.prevent="onDrop"        
  >
    <!-- ── Mobile collapsed pill ── -->
    <div
      v-if="isMobile && isMobileCollapsed"
      class="flex items-center gap-3 px-4 py-3 cursor-pointer"
      @click="expandMobile"
    >
      <i class="fa-solid fa-pen text-base-content/40 text-sm shrink-0"></i>
      <span class="text-base-content/40 text-sm flex-1 truncate">Write a message...</span>
      <i class="fa-solid fa-chevron-up text-base-content/30 text-xs"></i>
    </div>

    <!-- ── Full input (desktop always visible; mobile only when expanded) ── -->
    <template v-if="!isMobile || !isMobileCollapsed">
      <!-- Slot: extra content above the textarea (e.g. project selector) -->
      <div v-if="$slots['before-textarea']" class="px-2 md:px-3 pt-2 md:pt-3 pb-1">
        <slot name="before-textarea" />
      </div>

      <!-- Emoji Picker Popup -->
      <EmojiPicker
        v-if="cursorWord.word?.startsWith(':')"
        class="px-2 md:px-3 py-2 md:py-2 border-b border-base-300/50"
        :emoji-name="cursorWord.word"
        @emoji="onEmojiSelected"
      />

      <!-- Textarea — ghost style, expands naturally -->
      <div class="relative px-2 md:px-3 pt-2 md:pt-3">
        <textarea
          ref="editor"
          rows="3"
          class="w-full bg-transparent resize-none outline-none text-sm md:text-base text-base-content placeholder:text-base-content/30 leading-relaxed"
          :placeholder="isEditing ? 'Edit your message...' : 'Write something, or @ to mention a file...'"
          @keydown="$emit('keydown', $event)"
          @paste="$emit('paste', $event)"
          @focus="onFocus"
          @blur="onBlur"
          @input="onInput"
        ></textarea>
      </div>

      <!-- Divider -->
      <div class="mx-2 md:mx-3 border-t border-base-300/50 mt-1"></div>

      <!-- Toolbar -->
      <ChatInputToolbar
        :waiting="waiting"
        :is-editing="isEditing"
        :is-voice-session="isVoiceSession"
        :searching="searching"
        :read-only="readOnly"
        :selected-model="selectedModel"
        :ai-models="aiModels"
        :images="images"
        :profiles="profiles"
        :selected-profiles="selectedProfiles"
        :voice-language-label="voiceLanguageLabel"
        @send="onSend"
        @add-message="$emit('add-message')"
        @search-message="$emit('search-message')"
        @cancel-edit="$emit('cancel-edit')"
        @model-changed="$emit('model-changed', $event)"
        @toggle-search="$emit('toggle-search')"
        @hide-all="$emit('hide-all')"
        @attach-files="$emit('attach-files')"
        @test-project="$emit('test-project')"
        @toggle-voice="$emit('toggle-voice')"
        @remove-image="$emit('remove-image', $event)"
        @preview-image="$emit('preview-image', $event)"
        @profiles-selected="$emit('profiles-selected', $event)"
      />
    </template>
  </div>
</template>

<script>
export default {
  props: {
    waiting: Boolean,
    isEditing: Boolean,
    isVoiceSession: Boolean,
    searching: Boolean,
    readOnly: Boolean,
    selectedModel: String,
    aiModels: { type: Array, default: () => [] },
    images: { type: Array, default: () => [] },
    voiceLanguageLabel: String,
    profiles: { type: Array, default: () => [] },
    selectedProfiles: { type: Array, default: () => [] },
    cursorWord: { type: Object, default: () => ({}) }
  },
  emits: [
    'send', 'add-message', 'search-message', 'cancel-edit', 'model-changed',
    'toggle-search', 'hide-all', 'attach-files', 'test-project',
    'toggle-voice', 'remove-image', 'preview-image', 'keydown', 'paste',
    'drop', 'profiles-selected', 'focus', 'blur'
  ],
  data() {
    return {
      isFocused: false,
      isDraggingOver: false,
      isMobileCollapsed: true
    }
  },
  computed: {
    isMobile() {
      return this.$ui.isMobile
    }
  },
  watch: {
    isMobile(val) {
      if (!val) this.isMobileCollapsed = false
    },
    waiting(val) {
      if (!val && this.isMobile) {
        this.isMobileCollapsed = true
      }
    }
  },
  methods: {
    expandMobile() {
      this.isMobileCollapsed = false
      this.$nextTick(() => this.$refs.editor?.focus())
    },
    collapseMobile() {
      this.isMobileCollapsed = true
      this.$refs.editor?.blur()
    },
    onFocus() {
      this.isFocused = true
      this.$emit('focus')
    },
    onBlur() {
      this.isFocused = false
      this.$emit('blur')
      if (this.isMobile) {
        this.collapseMobile()
      }
    },
    onSend() {
      this.$emit('send')
      if (this.isMobile) {
        this.$nextTick(() => this.collapseMobile())
      }
    },
    onDrop(event) {
      this.isDraggingOver = false
      this.$emit('drop', event)
    },
    onInput() {
      this.autoResize()
      this.updateCursorWord()
    },
    getEditorText() {
      return this.$refs.editor?.value || ''
    },
    setEditorText(text) {
      if (this.$refs.editor) {
        this.$refs.editor.value = text
        this.autoResize()
      }
    },
    appendEditorText(text) {
      if (this.$refs.editor) {
        this.$refs.editor.value += text
        this.autoResize()
      }
    },
    focusEditor() {
      if (this.isMobile && this.isMobileCollapsed) {
        this.expandMobile()
        return
      }
      this.$refs.editor?.focus()
    },
    autoResize() {
      const el = this.$refs.editor
      if (!el) return
      el.style.height = 'auto'
      el.style.height = Math.min(el.scrollHeight, 320) + 'px'
    },
    getCaretWordInfo() {
      const textarea = this.$refs.editor
      if (!textarea) return {}
      const caretIndex = textarea.selectionStart
      const text = textarea.value
      let wordStart = caretIndex
      while (wordStart > 0 && /\S/.test(text[wordStart - 1])) {
        wordStart--
      }
      return {
        word: text.slice(wordStart, caretIndex),
        caretIndex
      }
    },
    updateCursorWord() {
      const wordInfo = this.getCaretWordInfo()
      this.$emit('update:cursor-word', wordInfo)
    },
    onEmojiSelected({ emoji }) {
      const textarea = this.$refs.editor
      if (!textarea) return

      const text = textarea.value
      const caretIndex = textarea.selectionStart

      let emojiStart = caretIndex
      while (emojiStart > 0 && /\S/.test(text[emojiStart - 1])) {
        emojiStart--
      }

      const newText = text.slice(0, emojiStart) + emoji + text.slice(caretIndex)
      textarea.value = newText

      const newCursorPos = emojiStart + emoji.length
      textarea.selectionStart = newCursorPos
      textarea.selectionEnd = newCursorPos

      this.autoResize()
      this.updateCursorWord()
      textarea.focus()
    }
  },
  expose: [
    'getEditorText',
    'setEditorText',
    'appendEditorText',
    'focusEditor',
    'getCaretWordInfo',
    'collapseMobile',
    'expandMobile'
  ]
}
</script>
```

